{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C52"],
      "claim": "Cibenzoline, which contains the same 2-imidazoline group as the query, has an absolute oral bioavailability of 80–90% in healthy subjects, strongly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C82"],
      "claim": "Midaglizole, another imidazoline-containing drug, has systemic bioavailability of at least 75% after oral administration in humans, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Metoclopramide, sharing chloro, methoxy, and basic amine features with the query, has absolute oral bioavailability of about 57% based on AUC in healthy subjects, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Brigatinib, a complex heteroaromatic basic amine, has oral bioavailability of approximately 46% in healthy volunteers, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C77"],
      "claim": "Alfuzosin, a methoxy-substituted heteroaromatic amine, has absolute oral bioavailability of 49% under fed conditions, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C73"],
      "claim": "Nifedipine has absolute oral bioavailability of 50–60% in humans despite extensive first-pass metabolism, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C57"],
      "claim": "Atazanavir has oral bioavailability of 69% under fasting conditions in humans, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Alprazolam has oral bioavailability of 80–100% in humans, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show absolute oral bioavailability well above 20%, with values ranging from about 46% to 100%. Direct imidazoline-containing analogues (cibenzoline, midaglizole) and chloro/methoxy/basic-amine analogues (metoclopramide, alfuzosin) support high F for the query. The physicochemical prior is mixed, but the strong, transferable experimental evidence outweighs it.",
  "evidence_gaps": [
    "No direct human pharmacokinetic data are available for the query molecule.",
    "First-pass metabolism and transporter involvement for the query are not experimentally characterized.",
    "The low logP and partial ionization of the query could affect permeability, but no affirmative evidence indicates F < 20%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

